<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Resumen de carga</title><style>:root{--ink:#201e1f;--turquoise:#5db8bc;--paper:#f6f8f8}body{margin:0;background:var(--paper);color:var(--ink);font-family:system-ui,sans-serif}.top{padding:14px 30px;border-bottom:5px solid var(--turquoise);background:#fff}.top img{width:115px}.page{max-width:1000px;margin:45px auto;padding:0 24px}.card{padding:28px;border-radius:12px;background:#fff;box-shadow:0 2px 10px #dce6e6}.total{font-size:34px;font-weight:800;color:#277d80}.grid{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin-top:24px}.box{border:1px solid #dce5e5;border-radius:10px;overflow:hidden}h2{margin:0;padding:14px 18px;border-bottom:3px solid var(--turquoise);font-size:18px}table{width:100%;border-collapse:collapse}th,td{padding:11px 18px;border-bottom:1px solid #edf1f1;text-align:left}th{background:#f4fbfb;color:#277d80;font-size:12px;text-transform:uppercase}td:last-child,th:last-child{text-align:right}.note{color:#60696b}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style></head><body><header class="top"><img src="{{ asset('images/logo4n.jpg') }}" alt="4N Logística"></header><main class="page"><p><a href="{{ route('provider-payments.courier-movements.upload') }}" style="color:#277d80">← Cargar otro archivo</a></p><h1>Resumen de carga</h1><section class="card"><p><b>Archivo:</b> {{ $validation['file_name'] }}</p><div class="total">{{ number_format($validation['records'],0,',','.') }} registros procesados</div><p class="note">{{ $validation['missing_tracking'] }} sin seguimiento · {{ $validation['invalid_date'] }} con fecha no identificable · {{ $validation['missing_weight'] }} sin peso.</p><div style="margin:20px 0;padding:18px;border-radius:10px;background:#eaf7f7"><b>¿Aceptas cargar esta información?</b><p class="note">Antes de incorporarla, revisaremos clientes, servicios, coberturas de comunas y pesos.</p><a href="{{ route('provider-payments.courier-movements.review-parameters') }}" style="display:inline-block;padding:11px 18px;border-radius:7px;background:#5db8bc;color:#fff;font-weight:700;text-decoration:none" id="review-link">Aceptar y revisar parámetros</a><div id="review-loading" hidden role="status"><p>Comparando clientes, servicios, coberturas y pesos…</p><progress aria-label="Revisando parámetros" style="width:100%;accent-color:#5db8bc"></progress></div></div><div class="grid"><article class="box"><h2>Registros por cliente</h2><table><thead><tr><th>Cliente / comerciante</th><th>Registros</th></tr></thead><tbody>@foreach($validation['merchant_counts'] as $name => $total)<tr><td>{{ $name }}</td><td>{{ number_format($total,0,',','.') }}</td></tr>@endforeach</tbody></table></article><article class="box"><h2>Registros por estado</h2><table><thead><tr><th>Estado</th><th>Registros</th></tr></thead><tbody>@foreach($validation['status_counts'] as $name => $total)<tr><td>{{ $name }}</td><td>{{ number_format($total,0,',','.') }}</td></tr>@endforeach</tbody></table></article></div></section></main><script>document.getElementById("review-link")?.addEventListener("click",function(){document.getElementById("review-loading").hidden=false;this.style.pointerEvents="none";});window.addEventListener("pageshow",function(){document.getElementById("review-loading").hidden=true;document.getElementById("review-link").style.pointerEvents="";});</script></body></html>
